 "content": "def transform(grid):
    # The vertical guide ray is color 2. Fill its full perpendicular track through
    # and beyond the 9-object's right edge, in color 8.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    obj_cols = [j for j in range(w) if any(grid[i][j] == 9 for i in range(h))]
    if obj_cols:
        c = max(obj_cols) + 1
        if c < w:
            for r in range(h):
                if grid[r][c] == 1:
                    out[r][c] = 8
    return out
